   [80]={next_id=81, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="女人把绷带一圈一圈缠在伤口上，手法极快。每一圈都平整紧贴。打结的时候多余的部分被利落地塞进夹层。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
