   [82]={next_id=83, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……蛰吻。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [83]={next_id=84, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="蛰吻……像毒蜂一样，潜藏在阴影中，一击毙命。", msg_color="", msg_size=0, talker="女人", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,1},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [84]={next_id=85, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="女人站起身，低头看了女孩最后一眼，从腰间的布包里又掏出一卷新的敷料，弯腰放在女孩面前的地上。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [85]={next_id=86, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="以后记得，受伤了就来找我。", msg_color="", msg_size=0, talker="女人", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,1},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [86]={next_id=87, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="女人转身走了，靴跟敲在地面上的声音干脆利落，很快就消失在训练场另一端的阴影里。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [87]={next_id=88, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……你叫什么名字？", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [88]={next_id=89, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="少女犹豫了片刻，还是对着女人消失的地方询问出声。阴影中，传来女人带着轻轻微笑的回复。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [89]={next_id=90, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我叫……芒刺。", msg_color="", msg_size=0, talker="芒刺", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [90]={next_id=91, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="从今天起，我就是你新的教官了。", msg_color="", msg_size=0, talker="芒刺", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [91]={next_id=92, abreast_id={}, pType =1, cg_type =5, dialog=0, msg="黑屏转场:arts/storyPrefab/prefab/common/prefab/StoryBlack.prefab", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="arts/storyPrefab/prefab/common/prefab/StoryBlack.prefab", runTalkTime =2000, destoryTime =4000, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [92]={next_id=93, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="少女在走廊里快步走着，赤脚踩在冰凉的岩石地面上尽量不发出声响。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [93]={next_id=94, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="那个叫芒刺的女人，自从上次帮少女治疗伤口之后，少女的心中出现了一种莫名感觉。暖暖的，与冰冷的地下世界截然不同。少女想要搞清楚这种感觉究竟是什么。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [94]={next_id=95, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她在一扇薄铁皮门前停下。门没有关严，门缝里透出摇曳的烛光。低声地呢喃透过门缝传入少女的耳中。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [95]={next_id=96, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="不能忘记……外面的世界……不要让“影巢”的洗脑影响到你……", msg_color="", msg_size=0, talker="芒刺", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [96]={next_id=97, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="那是芒刺的声音，是少女从未听过的语气。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [97]={next_id=98, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……还记得我曾登上过的那座山，漫山遍野都是树，风一吹叶子哗啦啦响。", msg_color="", msg_size=0, talker="芒刺", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [98]={next_id=99, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="那片我一直向往的海洋。很大很大，一眼望不到边。浪打在礁石上，泡沫是白的。", msg_color="", msg_size=0, talker="芒刺", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [99]={next_id=100, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="还有那些风，带来远方的味道和温度，吹在皮肤上暖洋洋的。", msg_color="", msg_size=0, talker="芒刺", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [100]={next_id=101, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="不能忘……", msg_color="", msg_size=0, talker="芒刺", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [101]={next_id=102, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="少女从门缝里看进去。芒刺跪在地上，面对着墙壁，手指在墙上一遍一遍地描画着什么。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [102]={next_id=103, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她在门外站了很久，她无法理解芒刺口中那个世界。芒刺说的每一个字都在冲击她的认知。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [103]={next_id=104, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她从来没有在地下世界见过这些东西，但她的脑子里却开始自动拼凑它们的样子，她不理解这种感觉，却也……不排斥。那些词语，那些景色，就像有魔力般深深吸引着她。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [104]={next_id=105, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="山……大海……风……", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [105]={next_id=106, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="少女跟着芒刺重复着那些词语，她蹲在门外，膝盖抵在冰凉的岩石地面上，一动也不动，就这样静静的听着。一颗向往的种子在少女心中悄然种下。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [106]={next_id=107, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="往后，少女时常会来到这里，也常常能遇到芒刺在自言自语。她屏住呼吸，从门缝里听芒刺对着墙壁念出那些词汇。少女的世界观在被重塑，心中的种子也在渐渐萌发。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [107]={next_id=108, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="几天后，少女照例蹲在门外。芒刺在说外面有一种东西叫雪，白色的，从天上飘下来，落在手心里会化成水。凉的，但不疼。她正在努力想象“凉但不疼”是什么感觉。忽然——", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [108]={next_id=109, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="门被猛地推开了。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [109]={next_id=110, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="少女条件反射的后撤步，压低重心，双手做出格挡的姿势……但，想象中的攻击并未到来。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [110]={next_id=111, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="芒刺站在门口，低头看着蹲在墙边的她。脸上的表情不是愤怒，也不是惊讶，而是嘴角翘起一个极淡的弧度。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [111]={next_id=112, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="少女没有动，维持着格挡架势，全身每一块肌肉都绷紧了。她的眼睛紧盯着芒刺。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [112]={next_id=113, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她知道地下世界的规则。在这里，偷听别人的秘密只有一种下场。她见过那些被拖出宿舍的人，再也没有回来过。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [113]={next_id=114, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="芒刺看着她，沉默了几秒。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [114]={next_id=115, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="进来。", msg_color="", msg_size=0, talker="芒刺", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [115]={next_id=116, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="少女愣住了，她不明白芒刺这句话的含义。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [116]={next_id=117, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……什么意思。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [117]={next_id=118, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我说，进来，坐到我身边来。", msg_color="", msg_size=0, talker="芒刺", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [118]={next_id=119, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="芒刺转身走回房间，没有关门。少女站在门外，看着那道敞开的门缝里透出的摇曳烛光，一动不动。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [119]={next_id=120, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她想不明白，按照组织的规则，芒刺现在应该动手了。就算不杀她，至少也会用更严厉的手段让她闭嘴。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [120]={next_id=121, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="但芒刺只是把门打开了，邀请她进去，就像邀请一个等了很久的人。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [121]={next_id=122, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="沉默片刻，她还是走了进去。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [122]={next_id=123, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="房间很小，一张床，一张桌，除此之外便什么都没有了。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [123]={next_id=124, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你不杀我?", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [124]={next_id=125, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="不杀。", msg_color="", msg_size=0, talker="芒刺", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,1},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [125]={next_id=126, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="为什么？我明明偷听了你的秘密。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [126]={next_id=127, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="芒刺靠在床头，双手交叉搭在膝上。她的眼睛看着女孩，平静，但带着一种从未出现过的温度。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [127]={next_id=128, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你觉得我在做什么？每天晚上对着墙说话？", msg_color="", msg_size=0, talker="芒刺", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,1},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [128]={next_id=129, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="蛰吻沉默了，她的眼睛扫过墙上那些刻痕，又落回芒刺脸上，没有说话。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [129]={next_id=130, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="看到少女的反应，芒刺的嘴角翘起一个弧度。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [130]={next_id=131, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="看来你的心里很清楚组织干的那些事……不错，看来我的选择是正确的。", msg_color="", msg_size=0, talker="芒刺", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,1},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [131]={next_id=132, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="组织每天都在往我们脑子里灌输东西，忠诚、服从、我们是武器。但我不能把那些东西当真。当真了，就真的只是一件武器了。", msg_color="", msg_size=0, talker="芒刺", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,1},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [132]={next_id=133, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="少女没有说话。她只是站在那里，看着芒刺。她不理解为什么有人会拒绝成为武器。武器不会痛苦、不会失望、只需要执行命令……这是她一直以来觉得理所当然的活法。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [133]={next_id=134, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我早就知道你在外面……从你第一次偷听的那天晚上就知道了。", msg_color="", msg_size=0, talker="芒刺", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,1},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [134]={next_id=135, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我故意把门开着一条缝，故意用你能听到的音量说话，就是……在测试你。", msg_color="", msg_size=0, talker="芒刺", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,1},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [135]={next_id=136, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……测试我？为什么？", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [136]={next_id=137, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我在找一个可以和我合作的伙伴。一个还没有被组织彻底改造、还有自己的脑子的人。", msg_color="", msg_size=0, talker="芒刺", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,1},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [137]={next_id=138, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你每天晚上都来，听了那么多外面的事，甚至你也猜到了我的目的。但你从来没有报告过，也没有对任何人谈论过这件事……你知道这意味着什么吗。", msg_color="", msg_size=0, talker="芒刺", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,1},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [138]={next_id=139, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="少女移开了目光。她的声音很低，像是第一次不知道该说什么。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [139]={next_id=140, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……我不知道。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [140]={next_id=141, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这意味着你在听到那些东西的时候，心中是对这些事物有向往的，并非像个真正机器一般无动于衷。", msg_color="", msg_size=0, talker="芒刺", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,1},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [141]={next_id=142, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这证明你还没有被组织改造得无可救药。你还有被拯救的价值。", msg_color="", msg_size=0, talker="芒刺", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,1},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [142]={next_id=143, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……你为什么要救我。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [143]={next_id=144, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="芒刺看着她，那个眼神和之前所有教官看她的眼神都不一样。不是在评估一把刀够不够锋利，而是在看一个……人。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [144]={next_id=145, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="因为我不想放弃一个值得被拯救的人，不想……再让另一个人重蹈我的覆辙……", msg_color="", msg_size=0, talker="芒刺", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,1},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [145]={next_id=146, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="芒刺重新坐回床边，拍了拍身边的位置。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [146]={next_id=147, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="过来吧。从今天开始，你可以直接进来听。不用蹲在门口。", msg_color="", msg_size=0, talker="芒刺", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,1},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [147]={next_id=148, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她犹豫了一瞬，但最终她还是走过去，在床沿坐了下来。那是她第一次坐在别人的床上，但她和芒刺之间仍保持着距离。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [148]={next_id=149, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="芒刺看到了少女的举动，却也没有多说什么，又开始讲外面的世界。她说她们所在的地方叫尤赞坦，里面有着形形色色的人和势力。还讲了莱斯坦斯，异变体，空天星链……", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [149]={next_id=150, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="少女静静听着，芒刺的每一个故事都在重塑她曾经的世界观，改造她的认知，她感觉心里的某种东西开始“跳动”。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [150]={next_id=151, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="黑暗中蜷缩的孩子，不要怕。", msg_color="", msg_size=0, talker="芒刺", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,1},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [151]={next_id=152, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="灰烬落尽的地方，会开出花。", msg_color="", msg_size=0, talker="芒刺", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,1},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [152]={next_id=153, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="萤火虫飞过坍塌的屋檐下。", msg_color="", msg_size=0, talker="芒刺", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,1},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [153]={next_id=154, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="芒刺哼起一首曲子。旋律很慢，很柔。像是从另一个世界漏进来的。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [154]={next_id=155, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……这是什么？", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [155]={next_id=156, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我家乡的摇篮曲。小时候母亲哄我睡觉的时候哼的。", msg_color="", msg_size=0, talker="芒刺", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,1},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [156]={next_id=157, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她偏过头看着芒刺。摇篮曲是什么，她没有概念。没有人哄过她睡觉。从记事起，她就是一个人躺在坚硬的床板上，听着走廊里的呻吟和远处的惨叫入眠。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [157]={next_id=158, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="但她把那段旋律记住了。第一个音符到最后，全都记住了。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [158]={next_id=159, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="天亮之前，我在这里，别害怕。", msg_color="", msg_size=0, talker="芒刺", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,1},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [159]={next_id=160, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="石缝里的草籽，也会发芽。", msg_color="", msg_size=0, talker="芒刺", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,1},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [160]={next_id=161, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="被遗忘的角落，也有光落下。", msg_color="", msg_size=0, talker="芒刺", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,1},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [161]={next_id=162, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你听见吗，远处有人在说话——", msg_color="", msg_size=0, talker="芒刺", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,1},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [162]={next_id=163, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="少女渐渐陷入沉睡，你的视线也逐渐开始模糊，但耳边摇篮曲的声音却越发清晰。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [163]={next_id=164, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="“回家吧，孩子，回家吧。”", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7214", 0, 0, -55, 223},{ 3, "7216", 0, 0, 49.5, 220.5}}, model_pos={{ 0,0,0},{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{},{}}, update_model={{ 2,0},{ 3,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [164]={next_id=165, abreast_id={}, pType =1, cg_type =5, dialog=0, msg="黑屏转场:arts/storyPrefab/prefab/common/prefab/StoryBlack.prefab", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1003.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="arts/storyPrefab/prefab/common/prefab/StoryBlack.prefab", runTalkTime =2000, destoryTime =4000, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [165]={next_id=166, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="“回家吧，孩子，回家吧。”", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/cg/cg_ACT308_104.jpg", video_url="", music_id="68", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [166]={next_id=167, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="意识逐渐回归本体，此刻的你仍身处那个避难所中，刚刚所经历的一切仿佛黄粱一梦。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/cg/cg_ACT308_104.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [167]={next_id=168, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你的身体轻轻一震，歌声也在此刻停止了。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/cg/cg_ACT308_104.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [168]={next_id=169, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……你醒了吗？", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/cg/cg_ACT308_101.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [169]={next_id=170, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她的声音有些沙哑，像是唱了很久，又像是刚刚睡醒。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/cg/cg_ACT308_101.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [170]={next_id=171, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你缓缓睁开眼睛。视线上方是一根合金管道，应急灯的光在管道边缘投下暖黄的轮廓。然后是一缕亚麻色的长发，垂落在你脸颊旁边，发梢轻轻蹭过你的耳廓。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/cg/cg_ACT308_101.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [171]={next_id=172, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你的后脑勺枕着一节柔软的藕臂，脸侧向一边，鼻尖贴着一片雪白的肌肤。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/cg/cg_ACT308_101.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [172]={next_id=173, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="每一次微弱的呼吸，都能闻到从她衣襟间传来的那股熟悉的香气，冷冽而温暖。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/cg/cg_ACT308_101.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [173]={next_id=174, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你意识到，自己正躺在蛰吻的怀里。她抱着你，像抱着一个睡着的孩子。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/cg/cg_ACT308_101.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [174]={next_id=175, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你轻微抬头，额头碰到了她的下巴。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/cg/cg_ACT308_101.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [175]={next_id=176, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="别动。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/cg/cg_ACT308_101.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [176]={next_id=177, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她的声音依然带着那种沙哑，但比刚才在通道里好多了。你这时才看清她——她的脸色虽然苍白，但比昏迷前好了不少。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/cg/cg_ACT308_101.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [177]={next_id=178, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她正低头看着你，目光里有一种你从未见过的神情，带着某种更柔软的、更深的、像是看着什么失而复得的东西时才会有的神情。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/cg/cg_ACT308_101.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [178]={next_id=179, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="蛰吻伸出手，用拇指轻轻擦掉你眼角的泪痕。她的指尖是温的，不再冰冷。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/cg/cg_ACT308_101.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [179]={next_id=180, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……蛰吻，你这样抱着我过去多久了？", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/cg/cg_ACT308_101.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [180]={next_id=181, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="链尉官，我的名字叫做赫芙蕊娅，你以后叫我赫芙蕊娅就好。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/cg/cg_ACT308_101.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [181]={next_id=182, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="蛰吻看着你，脸上尽是温柔之色。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/cg/cg_ACT308_101.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [182]={next_id=183, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你昏过去之后，没过多久我就醒了过来。看见你倒在地上，嘴边的血还没干。我探了你的脉搏，还好，只是毒性引起的心率过速。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/cg/cg_ACT308_101.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [183]={next_id=184, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我用星源共鸣的力量帮你解了毒，然后等着你醒来。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/cg/cg_ACT308_101.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [184]={next_id=185, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="但你一直在发抖，体温也有些冷。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/cg/cg_ACT308_101.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [185]={next_id=186, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="所以……我就把你抱进了怀里，想用我的体温帮你温暖一下身体。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/cg/cg_ACT308_101.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [186]={next_id=187, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="然后给我唱摇篮曲？", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/cg/cg_ACT308_101.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [187]={next_id=188, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="蛰吻耳根微微泛红，脸偏向一旁。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/cg/cg_ACT308_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [188]={next_id=189, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="因为你的表情很痛苦，嘴里一直在说些听不清的梦话。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/cg/cg_ACT308_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [189]={next_id=190, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你似乎是做梦了，并且是个不好的梦。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/cg/cg_ACT308_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [190]={next_id=191, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……嗯，我好像看到了一些幻影。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/cg/cg_ACT308_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [191]={next_id=192, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="看到什么？", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/cg/cg_ACT308_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [192]={next_id=193, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你的过去，影巢，还有……芒刺。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/cg/cg_ACT308_102.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [193]={next_id=194, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="蛰吻的动作顿了一下。她的手指停在你的太阳穴旁。过了许久，她轻轻嗯了一声。那声音很轻，却沉甸甸的，像一块石头终于被从河底捞了起来。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/cg/cg_ACT308_103.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [194]={next_id=195, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你我一同昏迷的时候，神血链接无意识地启动了。你看到的那些，或许并不是幻影。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/cg/cg_ACT308_103.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [195]={next_id=196, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="能和我讲讲你的过去吗？", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/cg/cg_ACT308_103.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [196]={next_id=197, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/cg/cg_ACT308_103.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [197]={next_id=198, abreast_id={}, pType =1, cg_type =5, dialog=0, msg="黑屏转场:arts/storyPrefab/prefab/common/prefab/StoryBlack.prefab", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/cg/cg_ACT308_103.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="arts/storyPrefab/prefab/common/prefab/StoryBlack.prefab", runTalkTime =2000, destoryTime =4000, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [198]={next_id=199, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="蛰吻坐起身穿好衣服，眼中似有追忆，似有痛苦。沉默良久，最终她轻轻开口。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [199]={next_id=200, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="影巢曾是活跃在尤赞坦地下世界的一个杀手组织。我尚在襁褓时被遗弃在尤赞坦的废墟里，后来被组织捡回去抚养。没有名字，只有代号。每天的课程只有一种——怎么杀人，怎么不被杀。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [200]={next_id=201, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她的声音很平，像在念一份与自己无关的报告。但你的余光注意到，她交叠的手指微微收紧了。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [201]={next_id=202, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="那个地方不需要情感。需要的是效率。受伤了不准哭，哭了会被罚。同伴倒下不准停下来，停下来就被淘汰。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [202]={next_id=203, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我在那里学会了怎么用毒，怎么调配香氛，怎么把任何东西变成武器。我学得很好。教官说我是第三十七期最优秀的作品。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [203]={next_id=204, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="作品……", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [204]={next_id=205, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="对，作品，不是人。我在那里的前十几年，对我而言周围的伙伴就像是空气，除了观察和利用，没有任何意义。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [205]={next_id=206, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="直到芒刺出现。她和所有人都不一样。她训练我的时候很严厉，但她会在训练结束后偷偷给我留吃的。她会找各种蹩脚的理由关心我。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [206]={next_id=207, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="说到这里，她的语气终于有了一丝波动。很轻，像水面被风吹皱的涟漪。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [207]={next_id=208, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她让我第一次知道——原来人可以不是武器。原来被关心不是弱点。原来这个世界上，还有一种东西叫“家人”。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [208]={next_id=209, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="可后来……", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [209]={next_id=210, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我将匕首亲手捅进芒刺的心脏。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [210]={next_id=211, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="为什么？芒刺不应该是你的“家人”吗？", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [211]={next_id=212, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="嗯，是我最重要的家人，对于我来说她就像“母亲”一样……但她是主动迎上匕首的。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [212]={next_id=213, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="芒刺的父母被影巢所杀，她潜伏在影巢中伺机复仇。她本来是打算趁着最终考核的机会刺杀首领，但首领从一开始就知道她的身份，就是想让她在最接近成功的那一刻，让她从希望落入绝望。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [213]={next_id=214, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="影巢的最终考核，是让同一期学员自相残杀。我活下来了，迈出阴暗的地牢，第一眼看到的便是倒在血泊中的芒刺。首领将匕首递给我，让我亲自捅进芒刺的心脏，否则就和她一起死。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [214]={next_id=215, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她闭上眼睛，睫毛微微颤动。房间里只剩下应急灯发出的微弱电流声。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [215]={next_id=216, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="芒刺为了保住我，主动迎上了匕首。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [216]={next_id=217, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [217]={next_id=218, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你张了张嘴，发现自己说不出任何话。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [218]={next_id=219, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="链尉官，我的真名叫做赫芙蕊娅。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [219]={next_id=220, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="但，你知道吗……赫芙蕊娅，这并非是我的名字。不，应该说我本来没有名字。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [220]={next_id=221, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="被影巢捡来的我，身边没有任何有关我身份的东西，我甚至不知道自己是不是在尤赞坦出生的。是芒刺在临死前，将她的名字给了我，让我替她活下去。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [221]={next_id=222, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="芒刺的理念便是不会放弃任何一个值得被拯救的人，就像她曾经拯救了我，所以我继承了芒刺的意志。几个月后，我对首领进行了暗杀……可惜失败了。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [222]={next_id=223, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="那你……", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [223]={next_id=224, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="很好奇我是怎么活下来的？", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [224]={next_id=225, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她睁开眼，嘴角弯起一个极淡的弧度。不是笑，而是一种自嘲。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [225]={next_id=226, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="首领有个恶趣味，那就是喜欢见到别人在痛苦与无助中精神崩溃，这也是为什么她发现芒刺的目的却并未直接出手的原因。她不断地给芒刺洗脑，看着她在痛苦中挣扎，直到最终收获的时刻。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [226]={next_id=227, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她对我的处罚也是一样。她们用数条被虚粒子污染的毒蜂去撕咬我，让我在毒液与虚粒子的折磨中痛苦的死去。毒液与虚粒子在我的血管中炸裂，我在剧痛中失去意识。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [227]={next_id=228, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她们以为我就此死去，将我的“尸体”随意丢弃，像处理其他的“废料”一样……可她们错了。我挺了过来，还觉醒了星源共鸣。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [228]={next_id=229, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我潜藏在影巢中，默默等待时机……等啊等，等啊等。芒刺对我的教导以及对影巢的仇恨支撑着我……终于，我等到了。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [229]={next_id=230, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她的呼吸重了一瞬，像是在压抑什么。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [230]={next_id=231, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="一年后，新一批孩子迎来最终考核。当教官们聚集在监控室欣赏杀戮时，我用一种无色无味的毒药杀死了他们……", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [231]={next_id=232, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="影巢被我摧毁，我带着那些还未被完全洗脑的孩子们逃了出来，组成了余烬。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [232]={next_id=233, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这便是我的故事……", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [233]={next_id=234, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [234]={next_id=235, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她的声音在最后几个字上微微发颤。很轻，像一片叶子落在水面上。但她的表情依然平静。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [235]={next_id=236, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你看着她，那些从她嘴里说出来的话，每一个字都比记忆里的画面更沉重。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [236]={next_id=237, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……我都不知道，你竟然还有这样的过去……", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [237]={next_id=238, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="蛰吻的手指微微收紧了。她低下头，亚麻色的长发遮住了她的侧脸。好一会儿，她只是看着自己被绷带缠紧的伤口。然后她开口了，声音依然平稳。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [238]={next_id=239, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这些年我想过很多次……芒刺不会希望我一直活在过去。所以我把过去锁在最深的地方，把力气用在建设余烬、照顾孩子、守护大空洞上。这么多年，我以为我已经放下了。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [239]={next_id=240, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="但今天在实验室里，那个黑袍人的出现。兜帽掉下来的时候，我看见她的脸……芒刺……", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [240]={next_id=241, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="当年我亲眼看着她倒在血泊里，胸口被贯穿，体温一点点变凉。她不可能活着……", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [241]={next_id=242, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="但我今天看到的就是她……不会错。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [242]={next_id=243, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她看着你，眼神里没有茫然，只有一种经历过许多事情的冷静。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [243]={next_id=244, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这件事情和影巢有关。当年我摧毁了影巢，但看来并没有斩草除根。而且死去的芒刺却复活了。我不相信她是真的芒刺，但我……也不能百分之百确定她不是。", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [244]={next_id=245, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我必须亲自调查清楚……", msg_color="", msg_size=0, talker="蛰吻", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4534", 0, 0, 28, 223}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [245]={next_id=246, abreast_id={}, pType =1, cg_type =5, dialog=0, msg="黑屏转场:arts/storyPrefab/prefab/common/prefab/StoryBlack.prefab", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT203_101.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="arts/storyPrefab/prefab/common/prefab/StoryBlack.prefab", runTalkTime =2000, destoryTime =4000, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [246]={next_id=247, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="大空洞 广场", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="70", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [247]={next_id=248, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="与矿道深处那种令人窒息的寂静不同，此刻的大空洞主城区正笼罩在一种紧绷的、一触即发的嘈杂中。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [248]={next_id=249, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="凯瑞公司的安保部队倾巢而出。穿着黑色制服的安保人员排成数列，沿着主街推进，脚步整齐而沉重，靴底在坑洼的岩石地面上踏出沉闷的节奏。领头的正是组特。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [249]={next_id=250, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="他的表情和之前在广场上与矿工们对峙时一模一样。严肃、冷漠，像一个被抽空了所有情绪的壳。只有握紧的拳头和微微颤抖的指节。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [250]={next_id=251, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="安保人员挨家挨户地砸门。拳头和棍棒砸在那些用木板和铁皮拼凑的门板上，发出震耳的闷响。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [251]={next_id=252, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="开门！凯瑞公司紧急体检！所有人出来！", msg_color="", msg_size=0, talker="凯瑞公司安保", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=1, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [252]={next_id=253, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="惊恐的居民被从家里驱赶出来，有男有女，有抱着婴儿的母亲，有刚从矿井里上来还没来得及换衣服的矿工。他们被安保人员粗鲁地推搡到主街中央，像牲口一样被驱赶到一起。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [253]={next_id=254, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="干什么！你们要干什么！", msg_color="", msg_size=0, talker="居民A", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [254]={next_id=255, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="闭嘴！往前走！", msg_color="", msg_size=0, talker="凯瑞公司安保", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [255]={next_id=256, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="一个老妇人被推得跌跌撞撞，踉跄了几步摔倒在地。安保人员看都没看她一眼，继续往前推搡。有人弯腰想去扶她，却被另一名安保推了回去。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [256]={next_id=257, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="米拉从人群中挤过来，一把扶起老妇人。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [257]={next_id=258, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你们凭什么抓人！", msg_color="", msg_size=0, talker="米拉", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [258]={next_id=259, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="组特转过身，看着这位曾经的儿时玩伴，他的嘴角抽搐了一下，但很快恢复了那副公事公办的表情。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7217", 0, 0, -53.5, 222.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [259]={next_id=260, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="矿区检测到大规模虚粒子污染。为了大家的健康和安全，凯瑞公司决定对所有居民进行强制性体检。请大家配合。", msg_color="", msg_size=0, talker="组特", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7217", 0, 0, -53.5, 222.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [260]={next_id=261, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="虚粒子污染？你骗谁呢！这地方虚粒子一直都有，怎么偏偏今天要“强制性体检”？我看你们是想把我们全都抓起来！", msg_color="", msg_size=0, talker="米拉", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7217", 0, 0, -53.5, 222.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [261]={next_id=262, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="正是因为昨天的事，公司才要彻查污染源头。余烬的人不是也在调查吗？说明污染确实存在。我们没有恶意，只是在做该做的事。", msg_color="", msg_size=0, talker="组特", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7217", 0, 0, -53.5, 222.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [262]={next_id=263, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="人群中爆发出一阵骚动。有人在哭喊，有人在咒骂，有孩子被吓哭了，尖细的哭声在这片嘈杂中格外刺耳。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7217", 0, 0, -53.5, 222.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [263]={next_id=264, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="组特哥哥！你还记得你曾是我们中的一员吗？！你这样做，艾朵会伤心的！", msg_color="", msg_size=0, talker="米拉", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7217", 0, 0, -53.5, 222.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [264]={next_id=265, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="组特没有回答只是站在那里，眼神空洞地越过她的肩膀，看向某个无人能及的方向。他攥紧的拳头在发抖，但他的声音依然平稳得像一潭死水。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7217", 0, 0, -53.5, 222.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [265]={next_id=266, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="为了大家的安全。请大家配合。", msg_color="", msg_size=0, talker="组特", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7217", 0, 0, -53.5, 222.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [266]={next_id=267, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="居民们被驱赶到凯瑞公司大楼前的广场上，凯瑞公司的医疗团队穿着白大褂站在大楼入口处，面前摆着一排折叠桌和便携式检测设备。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [267]={next_id=268, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我看就是体检而已……凯瑞公司以前也搞过体检，那次不也没什么事吗？", msg_color="", msg_size=0, talker="居民B", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [268]={next_id=269, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="是啊是啊，他们说要控制虚粒子污染，万一真有污染泄漏，我们去体检也是保护自己啊。", msg_color="", msg_size=0, talker="居民C", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [269]={next_id=270, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="上次体检，就是抽了几管血，什么也没发生。我们配合一下，明天就能正常下矿了。", msg_color="", msg_size=0, talker="居民D", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [270]={next_id=271, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="妥协的声音开始像潮水一样慢慢扩散。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [271]={next_id=272, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="人群中，一个不起眼的角落。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [272]={next_id=273, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="怎么办，现在动手吗？", msg_color="", msg_size=0, talker="余烬成员A", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [273]={next_id=274, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="家主还没回来，没有命令我们不能擅自出手。", msg_color="", msg_size=0, talker="余烬成员B", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [274]={next_id=275, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="凯瑞公司这次几乎出动了全部的安保力量，平时我们在家主的带领下与矿工们合作才与凯瑞公司分庭抗礼。可现在家主不在，矿工们又进入了矿区里……", msg_color="", msg_size=0, talker="余烬成员B", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [275]={next_id=276, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我们人手不够，万一真的冲突起来，孤儿院那边……怕是会遭到波及。", msg_color="", msg_size=0, talker="余烬成员B", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [276]={next_id=277, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="家主的命令，是让我们在发生冲突时保护好这些居民。现在凯瑞公司强行要带走这些居民，我们就这样干看着？", msg_color="", msg_size=0, talker="余烬成员A", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [277]={next_id=278, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……可要是他们是自愿的怎么办？", msg_color="", msg_size=0, talker="余烬成员B", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [278]={next_id=279, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……", msg_color="", msg_size=0, talker="余烬成员A", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [279]={next_id=280, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="执行B计划吧，希望来得及。", msg_color="", msg_size=0, talker="余烬成员B", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [280]={next_id=281, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="二人的身影无声无息的消失在人群中。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [281]={next_id=282, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="“配合一下”？难道以前发生过的那些事情大家都忘了吗？", msg_color="", msg_size=0, talker="米拉", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [282]={next_id=283, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="不是我们不反抗……你们想想，上次反抗的结果是什么？薪水降了，矿道封了，连精力剂都不发了。", msg_color="", msg_size=0, talker="居民B", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [283]={next_id=284, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="家里有老有小，天天要吃饭。我们不配合，还能怎么办？上次反正也过来了，说不定这次也只是……", msg_color="", msg_size=0, talker="居民B", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [284]={next_id=285, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="他没有说完。他不敢说完。但他低下了头，不敢看米拉的眼睛。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [285]={next_id=286, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="妥协的那一派人数更多。他们没有说话，只是慢慢地往广场中央挪了过去。有些人全家老小都站了出来，排成三三两两的队伍。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [286]={next_id=287, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="米拉看着那些人的背影，攥紧了拳头。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [287]={next_id=288, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="组特站在台阶上，一动不动地看着这一切，看着那些排着队往大楼里走的居民低着头从他身边经过。他的手指攥紧了又松开，松开了又攥紧。他的眼底有什么东西在翻涌。但他没有说一个字。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [288]={next_id=289, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="他抬起手，做了一个向前推进的手势。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [289]={next_id=-1, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="凯瑞公司的安保部队上前一步。盾牌和棍棒齐刷刷地举起，从左右两侧缓缓合拢，像一个正在收口的铁笼。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_ACT308_105.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
